    function managePlayer(uint256 _pID, CAE4Ddatasets.EventReturns memory _eventData_)
        private
        returns (CAE4Ddatasets.EventReturns)
    {


        if (plyr_[_pID].lrnd != 0)
            updateGenVault(_pID, plyr_[_pID].lrnd);


