    if (_start == 0) {
        revert();
    }

    startsAt = _start;

    if (_end == 0) {
        revert();
    }

    endsAt = _end;


    if (startsAt >= endsAt) {
        revert();
    }


    minimumFundingGoal = _minimumFundingGoal;
  }

