        bool enable;
    }
    struct Loan{
            uint256 Debt;

            uint256 Installment;
            uint256 Id;
            uint256 ForSale;
            address Client;
            address Owner;
            uint256 Category;
            uint256 Amount;
            uint256 StartTime;
            uint256 EndTime;
    }
    struct Portfolio{
        uint256[] idLoans;
        address Owner;
        uint256 forSale;
    }

    mapping(address => Client) clients;
    mapping(address => Bank) banks;
    Loan[] loans;

    function () public payable{
        require(false, "Should not go through this point");
    }


}
